#include <iostream>
#include <vector>
#include <string>
#include <string_view>
#include <algorithm>
#include <unordered_map>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<string> passwords(n);
    unordered_map<string, int> freq;
    freq.reserve(n * 2);

    for (int i = 0; i < n; ++i) {
        cin >> passwords[i];
        freq[passwords[i]]++;
    }

    long long total_pairs = 0;

    vector<string_view> subs;
    subs.reserve(55);

    for (int i = 0; i < n; ++i) {
        subs.clear();
        string_view s = passwords[i];
        int len = s.length();

        for (int start = 0; start < len; ++start) {
            for (int sub_len = 1; start + sub_len <= len; ++sub_len) {
                subs.push_back(s.substr(start, sub_len));
            }
        }

        sort(subs.begin(), subs.end());
        subs.erase(unique(subs.begin(), subs.end()), subs.end());

        for (const auto& sub : subs) {
            auto it = freq.find(string(sub));
            if (it != freq.end()) {
                total_pairs += it->second;
            }
        }
    }

    // Cada usuário conta a si mesmo exatamente uma vez, pois sua própria senha é uma subcadeia dela mesma.
    total_pairs -= n;

    cout << total_pairs << "\n";

    return 0;
}
